const joiningAliases:Record<string,string>={'Joining Category':'Joining Category *','Full Name':'Full Name *','Full Name as per Aadhaar':'Full Name as per Aadhar','Father / Spouse Name':'Father / Spouse Name *','Caste / Category':'Caste/category','Identification Mark':'Identification mark','Blood Group':'BLOOD GROUP','Mobile':'Mobile *','Candidate E-mail':'Candidate E-mail *','Aadhaar No.':'Aadhaar No. *','UAN No.':'UAN','ESIC':'ESIC Applicable','Site':'Site *','Department':'Department *','Sub-department':'Sub-department *','Designation':'Designation *','Joining Date':'Joining Date *','Shift':'Shift *','Salary Structure / Scheme':'Salary Structure /Scheme','Account No':'Bank Account No'};
const repeatedAliases:Record<string,string>={'Date of Birth':'Family Date of Birth','Designation':'Previous Designation'};
export function joiningOfficeData(values:Record<string,string>){
 const officeData:Record<string,unknown>={},repeated=new Map<string,string[]>();
 for(const [key,rawValue] of Object.entries(values)){
  const value=String(rawValue??'').trim();
  if(key.startsWith('Upload ')){if(value)officeData[key.slice(7)]=value;continue;}
  const match=key.match(/^(.*) (\d+)$/);
  if(match){if(!value)continue;const target=repeatedAliases[match[1]]||match[1],items=repeated.get(target)||[];items.push(value);repeated.set(target,items);continue;}
  officeData[joiningAliases[key]||key]=rawValue;
 }
 for(const [key,items] of repeated)officeData[key]=items.join(' | ');
 return officeData;
}
