 const lookup=new Map(fields.filter(([,value])=>value!=='').map(([name,value])=>[name.replace(/\s*\*$/,'').toLowerCase(),value]));
 const value=(column:string)=>lookup.get(column.replace(/\s*\*$/,'').toLowerCase())||lookup.get((joiningAliases[column]||column).replace(/\s*\*$/,'').toLowerCase())||'';
 const workbook=utils.book_new(),row=employeeExportColumns.map(value),sheet=utils.aoa_to_sheet([employeeExportColumns,row]);sheet['!cols']=employeeExportColumns.map(column=>({wch:Math.min(Math.max(column.length+2,14),38)}));utils.book_append_sheet(workbook,sheet,'Employee Form');
 const all=utils.aoa_to_sheet([['Field','Value'],...fields]);all['!cols']=[{wch:34},{wch:48}];utils.book_append_sheet(workbook,all,'All Fields');
