/* IFSC → bank and branch (public IFSC directory). Fills Branch Name, and Bank Name when it is empty. */
const ifscCache=new Map<string,{BANK?:string;BRANCH?:string;CITY?:string}|null>();
async function fillBranchFromIfsc(input:HTMLInputElement){const code=input.value.trim().toUpperCase();const form=input.form;if(!form)return;
 const branch=form.elements.namedItem('Branch Name') as HTMLInputElement|null,bank=form.elements.namedItem('Bank Name') as HTMLInputElement|null;
 if(!/^[A-Z]{4}0[A-Z0-9]{6}$/.test(code)){if(branch?.dataset.auto){branch.value='';delete branch.dataset.auto;}return;}
 let info=ifscCache.get(code);
 if(info===undefined){let fetched:{BANK?:string;BRANCH?:string;CITY?:string}|null=null;try{const res=await fetch(`https://ifsc.razorpay.com/${code}`);fetched=res.ok?await res.json():null;}catch{fetched=null;}info=fetched;ifscCache.set(code,info);}
 if(input.value.trim().toUpperCase()!==code)return;   /* user kept typing */
 if(!info){if(branch&&!branch.value)branch.placeholder='IFSC not found – enter branch manually';return;}
 if(branch&&(!branch.value||branch.dataset.auto)){branch.value=[info.BRANCH,info.CITY].filter(Boolean).join(', ');branch.dataset.auto='1';branch.dispatchEvent(new Event('change',{bubbles:true}));}
 if(bank&&(!bank.value||bank.dataset.auto)&&info.BANK){bank.value=info.BANK;bank.dataset.auto='1';bank.dispatchEvent(new Event('change',{bubbles:true}));}}
/* Hard input limits: digits only / length caps that paste and keyboard cannot bypass. */
const digits=(value:string)=>value.replace(/\D/g,'');
const inputLimits:Record<string,{max:number;clean:(value:string)=>string}>={'Mobile':{max:10,clean:digits},'Alternate Mobile':{max:10,clean:digits},'Emergency Contact Number':{max:10,clean:digits},'Aadhaar No.':{max:12,clean:digits},'PAN No.':{max:10,clean:value=>value.replace(/[^A-Z0-9]/g,'')},'IFSC Code':{max:11,clean:value=>value.toUpperCase().replace(/[^A-Z0-9]/g,'')},'Account No':{max:18,clean:digits},'UAN No.':{max:12,clean:digits},'ESIC':{max:10,clean:digits}   /* capitals and digits only – small letters are not accepted */};
function Field({label,required,placeholder='',type='text',options,wide,value,disabled,onChange,pattern,minLength,maxLength,inputMode,suggestions}:FieldProps){
 const id=label.toLowerCase().replace(/[^a-z0-9]+/g,'-');
 const mandatory=enforceJoiningMandatoryFields&&required;
 return <label className={'joining-field '+(wide?'wide':'')} htmlFor={id}><span>{label}{mandatory&&<b> *</b>}</span>{options?<select id={id} name={label} required={mandatory} disabled={disabled} value={value} onChange={onChange?event=>onChange(event.target.value):value!==undefined?()=>{}:undefined}><option value="">Select</option>{options.map(option=><option key={option} value={option}>{label==='Joining Category'?(companyNames[option]||option):label==='Site'?siteDisplayName(option):option}</option>)}</select>:type==='textarea'?<textarea id={id} name={label} required={mandatory} disabled={disabled} placeholder={placeholder}/>:<><FormInput id={id} name={label} list={suggestions?id+'-list':undefined} autoComplete={suggestions?'off':undefined} required={mandatory} disabled={disabled} type={type} min={label==='Joining Date'?'1000-01-01':undefined} max={label==='Joining Date'?'9999-12-31':undefined} onInput={label==='Joining Date'?event=>{const input=event.currentTarget;input.value=input.value.replace(/^(\d{4})\d+(?=-)/,'$1');}:inputLimits[label]?event=>{const input=event.currentTarget,rule=inputLimits[label],cleaned=rule.clean(input.value).slice(0,rule.max);if(cleaned!==input.value)input.value=cleaned;if(label==='IFSC Code')void fillBranchFromIfsc(input);}:undefined} placeholder={placeholder} pattern={pattern} minLength={minLength} maxLength={maxLength} inputMode={inputMode}/>{suggestions&&<datalist id={id+'-list'}>{suggestions.map(option=><option key={option} value={option} label={BANK_SHORT[option]}/>)}</datalist>}</>}</label>;
}
